</div>
/* Add @keyframes in animations.css */
```

## Step 4: State Integration

### Zustand Store Pattern

```tsx
import { createContext, useContext, useState } from "react";

interface MyState {
  items: Item[];
  isLoading: boolean;
  fetchItems: () => Promise<void>;
  addItem: (item: Item) => void;
}

const MyContext = createContext<MyState | null>(null);

export function MyProvider({ children }: { children: React.ReactNode }) {
  const [items, setItems] = useState<Item[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const fetchItems = async () => {
    setIsLoading(true);
    try {
      const items = await api.getItems();
      setItems(items);
    } finally {
      setIsLoading(false);
    }
  };

  const addItem = (item: Item) => {
    setItems(prev => [...prev, item]);
  };

  return (
    <MyContext.Provider value={{ items, isLoading, fetchItems, addItem }}>
      {children}
    </MyContext.Provider>
  );
}

export function useMyStore() {
  const context = useContext(MyContext);
  if (!context) throw new Error("useMyStore must be used within MyProvider");
  return context;
}
```

### Using Store in Components

```tsx
import { useChatStore } from "@/stores/chatStore";

function MyComponent() {
  const { messages, isLoading, sendMessage } = useChatStore();
  // ...
}
```

### React Query for Server State

```tsx
import { useQuery, useMutation } from "@tanstack/react-query";
import { api } from "@/api/client";

function MyComponent() {
  const { data, isLoading } = useQuery({
    queryKey: ["items"],
    queryFn: () => api.getItems(),
  });

  const mutation = useMutation({
    mutationFn: api.createItem,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["items"] });
    },
  });
}
```

### State Separation

- **Server state**: React Query (data from API)
- **Client state**: Zustand (UI preferences, local state)
- **Component state**: useState (ephemeral, component-scoped)

## Step 5: Testing with Vitest

### Test File Location

```
src/tests/
├── components/
│   └── my-component.test.tsx
└── setup.ts
```

### Test Pattern

```tsx
import { describe, it, expect, vi } from "vitest";
